insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('nanga', '南画', 'Nanga (Japanese literati painting)', 'japan', 1720, 1924,
        '中国の文人画にあこがれた日本の画家たちが、江戸時代中期から描いた絵画。文人画とも呼ばれ、詩・書・画を一体とします。', '南画は、中国の「南宗画」に由来する絵画を、日本の画家たちが独自に解釈して描いたものです。文人画とも呼ばれます。中国では、職業画家ではない学者や役人（文人）が、余技として心のままに描いた絵が高く評価されていました。明の董其昌は、元末四大家などに連なるこの流れを「南宗画」と名づけ、職業画家の流れ（北宗画）よりも上に置きました。

日本では、江戸時代の中ごろに中国から新しい画風が伝わりました。長崎に来た黄檗宗の僧や中国の画家、木版で刷られた絵の手本（画譜）がきっかけとなり、祇園南海や柳沢淇園、彭城百川らが描き始めます。その後、池大雅と与謝蕪村が南画を大成し、浦上玉堂、田能村竹田、谷文晁、渡辺崋山らが続きました。担い手は武士だけでなく、商人や俳人など身分をこえた人々で、地域をこえた文人同士の交わりの中から作品が生まれました。中国の手本をそのまま写すのではなく、大和絵など日本の要素も取り込み、詩と書と絵を一つの画面にまとめるのが特色です。明治時代になるとフェノロサや岡倉天心から低く評価されて勢いを失いますが、富岡鉄斎が力強い作品を残しました。

見るときは、画面に書かれた詩や句と絵がどう響き合っているかに注目してください。上手に見せるより、気持ちのままに引かれた線や、淡い色の温かさが見どころです。', 'https://ja.wikipedia.org/wiki/%E5%8D%97%E7%94%BB')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.movement_links (from_slug, to_slug, kind, note)
select a.slug, b.slug, 'influence', '元末四大家などに連なる中国の文人画（南宗画）が江戸時代に画譜などで伝わり、池大雅や与謝蕪村が日本の南画として大成しました。'
from public.art_movements a, public.art_movements b
where a.slug = 'song-yuan' and b.slug = 'nanga'
on conflict (from_slug, to_slug) do update set kind = excluded.kind, note = excluded.note;

insert into public.movement_links (from_slug, to_slug, kind, note)
select a.slug, b.slug, 'influence', '明治時代に衰えつつあった南画の流れの中から富岡鉄斎らが現れ、その活動が近代の「日本画」の成り立ちにもつながりました。'
from public.art_movements a, public.art_movements b
where a.slug = 'nanga' and b.slug = 'nihonga'
on conflict (from_slug, to_slug) do update set kind = excluded.kind, note = excluded.note;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('十便図', 'Ten Advantages', '池大雅', 'Ike no Taiga',
        1771,
        (select slug from public.art_movements where slug = 'nanga'),
        '川端康成記念会', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E6%B1%A0%E5%A4%A7%E9%9B%85%E3%80%8A%E5%8D%81%E4%BE%BF%E5%9B%B3_%E9%87%A3%E4%BE%BF%E5%9B%B3%E3%80%8B1771%E5%B9%B4%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg/960px-%E6%B1%A0%E5%A4%A7%E9%9B%85%E3%80%8A%E5%8D%81%E4%BE%BF%E5%9B%B3_%E9%87%A3%E4%BE%BF%E5%9B%B3%E3%80%8B1771%E5%B9%B4%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg', '明末から清初の中国の文人、李漁が山荘暮らしの楽しみを詠んだ詩をもとに、池大雅が「十の便利さ」を10図に描いた画帖です。同じ詩の「十の宜しさ」を与謝蕪村が描いた『十宜図』と組になり、1771年ごろに完成しました。依頼したのは鳴海宿の豪商・下郷学海で、作家の川端康成が後に所蔵しました。各図は約18センチ四方の小さな画面で、手に取って楽しむことができます。大雅のおおらかで軽やかな筆づかいからは、中国の文人の生活にあこがれた南画の精神が伝わってきます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

