insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('夜色楼台図', 'Snowclad Houses in the Night', '与謝蕪村', 'Yosa Buson',
        1778,
        (select slug from public.art_movements where slug = 'nanga'),
        '個人蔵', 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Snowclad_houses_in_the_night.jpg', '雪の降り積もった夜の町並みを、横に長い画面に描いた与謝蕪村の晩年の作品です。1778年から1783年ごろの制作と考えられています。夜空を墨で暗く塗り込めることで、屋根に積もった雪の白さを際立たせ、家々には人の暮らしの気配が感じられます。背後には雪をかぶった山並みが静かに続きます。中国の文人画の技法を用いながら、描かれているのは日本の冬の町の情景です。俳人でもあった蕪村の、静けさと温かさを同時に感じさせる詩的な表現が見どころです。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('東雲篩雪図', 'Snow Sifted Through Frozen Clouds', '浦上玉堂', 'Uragami Gyokudō',
        1811,
        (select slug from public.art_movements where slug = 'nanga'),
        '川端康成記念会', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/%E6%B5%A6%E4%B8%8A%E7%8E%89%E5%A0%82%E3%80%8A%E6%9D%B1%E9%9B%B2%E7%AF%A9%E9%9B%AA%E5%9B%B3%E3%80%8B19%E4%B8%96%E7%B4%80%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg/960px-%E6%B5%A6%E4%B8%8A%E7%8E%89%E5%A0%82%E3%80%8A%E6%9D%B1%E9%9B%B2%E7%AF%A9%E9%9B%AA%E5%9B%B3%E3%80%8B19%E4%B8%96%E7%B4%80%E3%80%81%E5%B7%9D%E7%AB%AF%E5%BA%B7%E6%88%90%E8%A8%98%E5%BF%B5%E4%BC%9A.jpg', '浦上玉堂が60代の終わりごろに描いたと推定される、玉堂の最高傑作とされる作品です。雪がふるいにかけたように降る冬の山を、墨の濃淡と、こすりつけるような細かな筆の重なりで表しています。文化財としての登録名は『凍雲篩雪図』ですが、玉堂自身は『東雲篩雪図』と名付けました。玉堂は武士の身分を捨てて琴と絵を友に各地を旅した文人で、その作品は形よりも心の動きを重んじています。この絵を高く評価した作家の川端康成が購入し、所蔵したことでも知られます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('鷹見泉石像', 'Portrait of Takami Senseki', '渡辺崋山', 'Watanabe Kazan',
        1837,
        (select slug from public.art_movements where slug = 'nanga'),
        '東京国立博物館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg/960px-A_portrait_of_Takami_Senseki_by_Watanabe_Kazan.jpg', '古河藩の家老で蘭学者でもあった鷹見泉石を、渡辺崋山が1837年に描いた肖像画です。背景を描かない正装の姿ですが、頬や目のまわりには西洋画の陰影法が使われ、顔に立体感が生まれています。淡い彩色は水彩画を思わせます。崋山は南画家の谷文晁に学びつつ、蘭学を通して西洋の絵画にも関心をもちました。南画の筆づかいと西洋の写実を組み合わせたこの作品は、江戸時代の終わりに、日本の絵画が西洋と出会い始めていたことを示しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
